"/* Sliding Provider Selector (Local ● Cloud) */
.provider-selector {
  position: relative;
  display: inline-flex;
  align-items: center;
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-full);
  padding: 3px;
  backdrop-filter: blur(8px);
  user-select: none;
}

.provider-slider {
  position: absolute;
  top: 3px;
  left: 3px;
  width: calc(50% - 3px);
  height: calc(100% - 6px);
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-full);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
  transition: transform var(--transition-normal);
  z-index: 1;
}

.provider-selector.cloud-active .provider-slider {
  transform: translateX(100%);
}

.provider-option {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.9rem;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.825rem;
  font-weight: 500;
  cursor: pointer;
  transition: color var(--transition-fast);
  border-radius: var(--radius-full);
}

.provider-option .provider-dot {
  width: 6px;
  height: 6px;
  border-radius: var(--radius-full);
  background-color: var(--text-muted);
  transition: background-color var(--transition-fast);
}

.provider-option.active {
  color: var(--text-primary);
}

.provider-option[data-provider="ollama"].active .provider-dot {
  background-color: var(--accent-cyan);
  box-shadow: 0 0 6px var(--accent-cyan);
}

.provider-option[data-provider="gemini"].active .provider-dot {
  background-color: var(--accent-amber);
  box-shadow: 0 0 6px var(--accent-amber);
}"

