    if (activeSkill.name === "artifact-html" || text.includes("<div") || text.includes("<!DOCTYPE") || text.includes("<html")) {
      // Extract HTML block if enclosed in markdown code fences
      let htmlCode = text;
      const htmlMatch = text.match(/```(?:html)?\s*([\s\S]*?)```/i);
      if (htmlMatch) {
        htmlCode = htmlMatch[1].trim();
      }
      artifact = {
        type: "html",
        title: "Visual Summary",
        content: htmlCode,
      };
    } else if (activeSkill.name === "artifact-markdown" || options.prompt.toLowerCase().includes("markdown")) {
      let mdCode = text;
      const mdMatch = text.match(/```(?:markdown|md)?\s*([\s\S]*?)```/i);
      if (mdMatch) {
        mdCode = mdMatch[1].trim();
      }
      artifact = {
        type: "markdown",
        title: "Markdown Document",
        content: mdCode,
      };
    } else if (activeSkill.name === "ship30" || options.prompt.toLowerCase().includes("essay") || options.prompt.toLowerCase().includes("article")) {
      content = {
        type: "article",
        title: "Ship 30 Essay",
        content: text,
      };
    } else if (activeSkill.name === "structured-content") {
      const lower = options.prompt.toLowerCase();
      const cType = lower.includes("compare") ? "comparison" : lower.includes("key point") || lower.includes("takeaway") ? "key_points" : "summary";
      content = {
        type: cType,
        title: cType.replace("_", " ").toUpperCase(),
        content: text,
      };
    }
  }

  return {
    ...rawResult,
    skill_invoked: activeSkill ? activeSkill.name : null,
    content,
    artifact,
  };
